-- S-06: edit and delete any entry. expenses and incomes gain UPDATE and DELETE policies for the whole household
-- (replacing the narrow "delete generated rows only" policies from S-04 / S-05).
-- Every policy filters by (select public.current_household_id()) - see context/foundation/lessons.md.
--
-- Rule enforced in the database, so no write path can bypass it: an entry generated by a recurring definition
-- (recurring_*_id is not null) may only change its amount (expenses also their description, which a definition does
-- not carry yet). The recurring RPCs (update amount / extend / stop) only DELETE and INSERT rows, never UPDATE them,
-- so these triggers do not get in their way.
-- Columns are compared one by one with IS DISTINCT FROM (null-safe), not as whole rows, so adding a column later
-- cannot silently change what is locked.

create function public.expenses_guard_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  -- Never changeable, for any entry.
  if new.household_id is distinct from old.household_id
     or new.recurring_expense_id is distinct from old.recurring_expense_id
     or new.created_at is distinct from old.created_at then
    raise exception 'household_id, recurring_expense_id and created_at of an entry cannot be changed'
      using errcode = '22023';
  end if;

  -- A generated entry: only the amount and the description may change.
  if old.recurring_expense_id is not null
     and (new.category_id is distinct from old.category_id
          or new.spent_on is distinct from old.spent_on) then
    raise exception 'a generated entry can only change its amount and description' using errcode = '22023';
  end if;

  return new;
end;
$$;

create trigger expenses_guard_update
  before update on public.expenses
  for each row execute function public.expenses_guard_update();

create function public.incomes_guard_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.household_id is distinct from old.household_id
     or new.recurring_income_id is distinct from old.recurring_income_id
     or new.created_at is distinct from old.created_at then
    raise exception 'household_id, recurring_income_id and created_at of an entry cannot be changed'
      using errcode = '22023';
  end if;

  if old.recurring_income_id is not null
     and (new.source is distinct from old.source
          or new.received_on is distinct from old.received_on) then
    raise exception 'a generated entry can only change its amount' using errcode = '22023';
  end if;

  return new;
end;
$$;

create trigger incomes_guard_update
  before update on public.incomes
  for each row execute function public.incomes_guard_update();

-- Supabase grants EXECUTE on new public functions to anon/authenticated (see 20261008200524_revoke_function_execute).
-- Trigger functions are never called directly, so nobody needs the grant.
revoke execute on function public.expenses_guard_update() from public, anon, authenticated;
revoke execute on function public.incomes_guard_update() from public, anon, authenticated;

drop policy "expenses_delete_generated" on public.expenses;
drop policy "incomes_delete_generated" on public.incomes;

create policy "expenses_update" on public.expenses
  for update to authenticated
  using (household_id = (select public.current_household_id()))
  with check (household_id = (select public.current_household_id()));

create policy "expenses_delete" on public.expenses
  for delete to authenticated
  using (household_id = (select public.current_household_id()));

create policy "incomes_update" on public.incomes
  for update to authenticated
  using (household_id = (select public.current_household_id()))
  with check (household_id = (select public.current_household_id()));

create policy "incomes_delete" on public.incomes
  for delete to authenticated
  using (household_id = (select public.current_household_id()));
